import java.util.Arrays;
import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int n = scanner.nextInt();
        int m = scanner.nextInt();
        int[] a = new int[n];
        for (int i = 0; i < n; i++) {
            a[i] = scanner.nextInt();
        }
        int[] b = new int[1 << ((n / 2) + (n % 2))];
        int index = 0;
        int limit1 = 1 << ((n / 2) + (n % 2));
        for (int i = 0; i < limit1; i++) {
            int t = 0;
            int k = i;
            for (int j = 0; j < 20; j++) {
                if ((k & 1) == 1) {
                    t += a[j];
                }
                k >>= 1;
            }
            b[index++] = t % m;
        }
        Arrays.sort(b);
        int otv = 0;
        int limit2 = 1 << (n / 2);
        for (int i = 0; i < limit2; i++) {
            int t = 0;
            int k = i;
            for (int j = 0; j < 20; j++) {
                if ((k & 1) == 1) {
                    t += a[(n / 2) + (n % 2) + j];
                }
                k >>= 1;
            }
            t = t % m;
            int idx = Arrays.binarySearch(b, m - t - 1);
            if (idx < 0) {
                idx = -idx - 1;
            }
            int t2;
            if (idx < b.length) {
                t2 = b[idx];
                if (t2 > m - t - 1 && idx - 1 >= 0) {
                    t2 = b[idx - 1];
                }
            } else {
                t2 = b[b.length - 1];
            }
            otv = Math.max(otv, Math.max((t + t2) % m, (t + b[b.length - 1]) % m));
        }
        System.out.println(otv % m);
        scanner.close();
    }
}
